def fmt_table(rows):
    ncols = len(rows[0])
    normalized = [list(row) + [''] * (ncols - len(row)) for row in rows]

    widths = [max(len(row[c]) for row in normalized) for c in range(ncols)]

    def border():
        return '+' + '+'.join('-' * (w + 2) for w in widths) + '+'

    def is_numeric(s):
        try:
            float(s)
            return True
        except (ValueError, TypeError):
            return False

    def format_row(row, header):
        parts = []
        for i, cell in enumerate(row):
            if header:
                parts.append(cell.ljust(widths[i]))
            elif is_numeric(cell):
                parts.append(cell.rjust(widths[i]))
            else:
                parts.append(cell.ljust(widths[i]))
        return '|' + '|'.join(' ' + p + ' ' for p in parts) + '|'

    lines = [border()]
    lines.append(format_row(normalized[0], True))
    lines.append(border())
    for row in normalized[1:]:
        lines.append(format_row(row, False))
    lines.append(border())

    return '\n'.join(lines)
